        if (!isRangeUsable(left) || !isRangeUsable(right)) {
            return false;
        }

        try {
            return left.compareBoundaryPoints(left.START_TO_START, right) === 0
                && left.compareBoundaryPoints(left.END_TO_END, right) === 0;
        }
        catch (x) {
            return false;
        }
