                dialoginner.__aiResolved = resolved;
                dialoginner.__aiOperationStates = {};
                dialoginner.__aiPlanStale = false;
                dialoginner.__aiPlanStaleReason = "";
                dialoginner.__aiPlanStaleAction = "";
